def _verbs():
    out = []
    for name, summary, inp, outp, timeout, status, longr, ex in _T:
        if name.endswith("_note"):
            continue
        out.append({
            "name": name,
            "summary": summary,
            "input": inp,
            "output": outp,
            "timeoutSeconds": timeout,
            "statusVerb": status,
            "longRunning": longr,
            "example": ex,
        })
    return out


def handle_describe(args: dict) -> dict:
    verbs = _verbs()
    # `verbs` at the TOP LEVEL is what ab's Verbs tab reads from the raw /command
    # response. ab's relay strips non-standard top-level fields on the CLI proxy
    # path, so we ALSO nest under `data` (which the relay forwards) for CLI/debug.
    return {
        "success": True,
        "bridge": "fusion360",
        "verbCount": len(verbs),
        "verbs": verbs,
        "data": {"bridge": "fusion360", "verbCount": len(verbs), "verbs": verbs},
    }
